solutions.naive:
class Solution:
    def missingNumber(self, nums: list[int]) -> int:
        for x in range(len(nums) + 1):
            if x not in nums:
                return x
        return -1

solutions.better:
class Solution:
    def missingNumber(self, nums: list[int]) -> int:
        vals = set(nums)
        for x in range(len(nums) + 1):
            if x not in vals:
                return x
        return -1

solutions.optimal:
class Solution:
    def missingNumber(self, nums: list[int]) -> int:
        n = len(nums)
        return n * (n + 1) // 2 - sum(nums)

